<script setup>
import { computed, reactive, ref, watch } from 'vue'
import FloatingWindow from '../common/FloatingWindow.vue'
import { useAppStore } from '../../stores/app'
const open = defineModel({ default: false }); const store = useAppStore(); const step = ref(1); const loading = ref(false); const error = ref(''); const discovered = ref([]); const selectedIds = ref([]); const imported = ref([]); const wizard = reactive({ connectorId: '', defaultCredentialId: '', credentialIds: {} })
const connectors = computed(() => store.catalog.settings.xenserver?.connectors || []); const credentials = computed(() => store.catalog.credentials || []); const selected = computed(() => discovered.value.filter((item) => selectedIds.value.includes(item.id)))
watch(open, (value) => { if (value) { step.value = 1; error.value = ''; discovered.value = []; selectedIds.value = []; imported.value = []; wizard.connectorId = connectors.value[0]?.id || ''; wizard.defaultCredentialId = ''; wizard.credentialIds = {} } })
async function discover() { if (!wizard.connectorId) return void (error.value = 'Choose a XenServer connector first.'); loading.value = true; error.value = ''; try { discovered.value = await store.discoverXenServer(wizard.connectorId); selectedIds.value = discovered.value.map((item) => item.id) } catch (cause) { error.value = cause.message } finally { loading.value = false } }
function applyCredential() { selected.value.forEach((item) => { wizard.credentialIds[item.id] = wizard.defaultCredentialId }) }
async function importSelected() { loading.value = true; error.value = ''; try { imported.value = await store.importXenServerSelection(wizard.connectorId, selectedIds.value, wizard.credentialIds); step.value = 3 } catch (cause) { error.value = cause.message } finally { loading.value = false } }
</script>
<template><FloatingWindow v-model="open" title="Import XenServer / XCP-ng Machines" :width="790" :start-x="195" :start-y="95"><v-window v-model="step"><v-window-item :value="1"><section class="wizard-stage"><div class="stage-intro"><p class="section-eyebrow">Step 01 / XenAPI Inventory</p><h3>Choose guests from a XenServer or XCP-ng pool.</h3><span>Discovery uses read-only XenAPI JSON-RPC and excludes control domains.</span></div><div class="discovery-bar"><v-select v-model="wizard.connectorId" :items="connectors" item-title="name" item-value="id" label="XenServer connector" density="compact" hide-details/><v-btn class="glass-button" :loading="loading" @click="discover">Discover</v-btn></div><v-alert v-if="error" type="error" density="compact" variant="tonal">{{ error }}</v-alert><div v-if="discovered.length" class="machine-list"><article v-for="machine in discovered" :key="machine.id" class="machine-row"><v-switch v-model="selectedIds" :value="machine.id" density="compact" color="secondary" hide-details/><div><strong>{{ machine.name }}</strong><span>{{ machine.guestOs || 'Guest OS not reported' }} · {{ machine.ipAddress || 'No guest IP' }} · {{ machine.powerState }}</span></div></article></div><p v-else class="empty-panel">Add a XenServer connector in System Settings, then discover its pool inventory.</p><div class="wizard-actions"><v-btn variant="text" @click="open = false">Cancel</v-btn><v-btn class="glass-button" :disabled="!selectedIds.length" @click="step = 2">Assign Credentials</v-btn></div></section></v-window-item><v-window-item :value="2"><section class="wizard-stage"><div class="stage-intro"><p class="section-eyebrow">Step 02 / Access Binding</p><h3>Assign credentials before importing nodes.</h3></div><div class="credential-bar"><v-select v-model="wizard.defaultCredentialId" :items="credentials" item-title="name" item-value="id" label="Apply credential to selected guests" density="compact" hide-details/><v-btn variant="text" :disabled="!wizard.defaultCredentialId" @click="applyCredential">Apply all</v-btn></div><article v-for="machine in selected" :key="machine.id" class="assignment-row"><strong>{{ machine.name }}</strong><v-select v-model="wizard.credentialIds[machine.id]" :items="credentials" item-title="name" item-value="id" label="Remoting credential" density="compact" hide-details/></article><div class="wizard-actions"><v-btn variant="text" @click="step = 1">Back</v-btn><v-btn class="glass-button" :loading="loading" :disabled="selected.some((item) => !wizard.credentialIds[item.id])" @click="importSelected">Import Machines</v-btn></div></section></v-window-item><v-window-item :value="3"><section class="wizard-stage"><div class="stage-intro"><p class="section-eyebrow">Import Complete</p><h3>{{ imported.length }} machines added to Node Inventory.</h3><span>They remain linked to their XenServer/XCP-ng source for managed inventory reconciliation.</span></div><div class="wizard-actions"><v-btn class="glass-button" @click="open = false">Finish</v-btn></div></section></v-window-item></v-window></FloatingWindow></template>
<style scoped>.wizard-stage,.machine-list{display:grid;gap:14px}.stage-intro{display:grid;gap:5px}.stage-intro p,.stage-intro h3{margin:0}.stage-intro span,.machine-row span,.empty-panel{color:var(--muted);font-size:.78rem}.discovery-bar,.credential-bar,.wizard-actions{display:flex;gap:9px;align-items:center}.discovery-bar .v-input,.credential-bar .v-input{flex:1}.machine-row,.assignment-row{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:center;padding:10px;border:1px solid var(--line);background:rgba(40,211,255,.04)}.machine-row div{display:grid;gap:3px}.assignment-row .v-input{grid-column:2}.wizard-actions{justify-content:flex-end}@media(max-width:600px){.discovery-bar,.credential-bar{align-items:stretch;flex-direction:column}}</style>
